import sys

data = sys.stdin.read().split()
n = int(data[0])
edges = []
p = 1
for _ in range(n - 1):
    edges.append((int(data[p]), int(data[p + 1]), int(data[p + 2])))
    p += 3
deg = [0] * n
for u, v, w in edges:
    deg[u] += 1
    deg[v] += 1
leaves = [i for i in range(1, n) if deg[i] == 1]
best = None
for mask in range(1 << (n - 1)):
    cost = 0
    adj = [[] for _ in range(n)]
    for i, (u, v, w) in enumerate(edges):
        if mask >> i & 1:
            cost += w
        else:
            adj[u].append(v)
            adj[v].append(u)
    if best is not None and cost >= best:
        continue
    seen = {0}
    st = [0]
    while st:
        x = st.pop()
        for y in adj[x]:
            if y not in seen:
                seen.add(y)
                st.append(y)
    if all(l not in seen for l in leaves):
        best = cost
print(best)

