def gen(rng):
    def build(n, parents, weights):
        perm = list(range(1, n))
        rng.shuffle(perm)
        lab = [0] + perm
        edges = []
        for i in range(1, n):
            a, b = lab[parents[i]], lab[i]
            if rng.random() < 0.5:
                a, b = b, a
            edges.append(f'{a} {b} {weights[i]}')
        rng.shuffle(edges)
        return str(n) + '\n' + '\n'.join(edges)
    def rand_tree(n, wmax, kind='random'):
        parents = [0] * n
        for i in range(1, n):
            if kind == 'random':
                parents[i] = rng.randrange(i)
            elif kind == 'chain':
                parents[i] = i - 1
            elif kind == 'star':
                parents[i] = 0
            elif kind == 'binary':
                parents[i] = (i - 1) // 2
            elif kind == 'deep':
                parents[i] = max(0, i - 1 - rng.randint(0, 3))
            elif kind == 'caterpillar':
                parents[i] = i - 2 if i % 2 == 0 and i >= 2 else (i - 1 if i % 2 == 1 else 0)
        weights = [0] + [rng.randint(1, wmax) for _ in range(1, n)]
        return build(n, parents, weights)
    tests = []
    tests.append(build(2, [0, 0], [0, 5]))
    tests.append(build(3, [0, 0, 1], [0, 1, 1]))
    tests.append(build(3, [0, 0, 0], [0, 4, 9]))
    tests.append(build(4, [0, 0, 1, 2], [0, 10, 10, 10]))
    tests.append(build(4, [0, 0, 1, 2], [0, 1, 100, 100]))
    for _ in range(40):
        n = rng.randint(2, 11)
        kind = rng.choice(['random', 'random', 'chain', 'star', 'binary', 'deep'])
        tests.append(rand_tree(n, rng.choice([3, 10, 20]), kind))
    for kind in ('random', 'chain', 'star', 'binary', 'deep', 'caterpillar'):
        tests.append(rand_tree(rng.randint(500, 3000), 10**6, kind))
    for kind in ('random', 'chain', 'binary', 'deep', 'caterpillar'):
        tests.append(rand_tree(100000, 10**6, kind))
    tests.append(rand_tree(100000, 10, 'random'))
    return tests

